    net: { proto: (cf.httpProtocol || ''), tls: (cf.tlsVersion || ''), cipher: (cf.tlsCipher || ''), rtt: (cf.clientTcpRtt != null ? String(cf.clientTcpRtt) : ''), colo: (cf.colo || '') },
    ref: H('Referer'), lang: H('Accept-Language')
