function _b64url(str) { return b64(enc(str)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''); }
function _b64urlToStd(s) { s = String(s || '').replace(/-/g, '+').replace(/_/g, '/'); while (s.length % 4) s += '='; return s; }
