    var cents = _qbPaidCents(d);
    if (!(cents > 0)) return;
    var dn = (String((d && (d.custName || d.cust || d.name || d.customer)) || 'Customer').replace(/[\\'"\r\n]+/g, ' ').replace(/\s+/g, ' ').trim() || 'Customer').slice(0, 100);
    var base = ACCT.xero.api + '/api.xro/2.0';
