    if (String(await _pcfgGet(env, 'gmv_connect_ready', '0')) !== '1') return { on: false };   // HARD 2nd gate: stays OFF until the Connect-aware REFUND + webhook paths are built + tested. Never enable this before then -- a charge without a working refund is a money bug.
    var acct = connRow && connRow.stripe_connect_acct;
