    construction: { hd: 'Your rental', noun: 'rental', back: 'return', ph: 'Delivery / condition photos', req: 'e.g. 2 more days, or another attachment' },
    equip: { hd: 'Your rental', noun: 'rental', back: 'return', ph: 'Pickup / condition photos', req: 'e.g. 1 more day, or extra accessories' },
    trailer: { hd: 'Your rental', noun: 'rental', back: 'return', ph: 'Pickup / condition photos', req: 'e.g. 1 more day, or extra straps' },
